<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Đơn hàng</th><th>Khách hàng</th><th>Tiền sách</th><th>Trạng thái</th><th>Đối soát COD & Đổi trả</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $row): [$statusLabel, $statusColor] = order_status($row['trangThai']); [$codText, $codColor] = cod_status($row['trangThaiCOD'] ?? 'ChuaThu'); ?><tr><td><a class="admin-link" href="<?= e(url('admin-order', ['id' => $row['maDH']])) ?>">#<?= e($row['maDH']) ?></a><small><?= e($row['ngayTao'] ?: 'Chưa ghi nhận ngày') ?></small></td><td><strong><?= e($row['tenND']) ?></strong><small><?= e($row['email']) ?></small></td><td class="admin-nowrap"><?= e(money($row['total'])) ?></td><td><span class="admin-badge <?= e($statusColor) ?>"><?= e($statusLabel) ?></span></td><td><span class="admin-badge <?= e($codColor) ?>"><?= e($codText) ?></span><?php if (!empty($row['trangThaiDoiTra'])): [$retText, $retColor] = return_status($row['trangThaiDoiTra']); ?><br><span class="admin-badge <?= e($retColor) ?>" style="margin-top: 4px; display: inline-block;">Đổi trả: <?= e($retText) ?></span><?php endif; ?></td><td><a class="admin-link" href="<?= e(url('admin-order', ['id' => $row['maDH']])) ?>" aria-label="Xem đơn #<?= e($row['maDH']) ?>">Chi tiết</a></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6"><div class="admin-empty"><?= icon('box') ?><h3>Chưa có đơn hàng</h3><p>Đơn hàng được lưu trong hệ thống sẽ xuất hiện tại đây.</p></div></td></tr><?php endif; ?>
</tbody></table></div>
